supervisor_source:
$ErrorActionPreference = 'Stop'
$runRoot = 'D:\论文复现\experiments\local_structure_20260930'
$sourceRoot = Join-Path $runRoot 'src\PaddleSeg-2.10.0'
$pythonExe = 'C:\Users\user\算法实验\venv_bisenet\Scripts\python.exe'
$env:PYTHONPATH = $sourceRoot
$env:PYTHONIOENCODING = 'utf-8'
$env:PYTHONUTF8 = '1'
$statePath = Join-Path $runRoot 'results\queue_state.json'
$finished = @()
try {
  foreach ($variant in @('C1','C2')) {
    $configPath = Join-Path $runRoot "configs\$variant.yml"
    $outputPath = Join-Path $runRoot "training\$variant"
    if (Test-Path -LiteralPath $outputPath) { throw "Training output already exists: $outputPath" }
    $arguments = @('"' + (Join-Path $sourceRoot 'tools\train.py') + '"', '--config', '"' + $configPath + '"', '--save_dir', '"' + $outputPath + '"', '--save_interval', '1000', '--log_iters', '100', '--keep_checkpoint_max', '2', '--seed', '42', '--num_workers', '0', '--use_ema', '--do_eval', '--device', 'gpu', '--precision', 'fp32')
    $started = (Get-Date).ToString('o')
    $process = Start-Process -FilePath $pythonExe -ArgumentList $arguments -WorkingDirectory $sourceRoot -WindowStyle Hidden -RedirectStandardOutput (Join-Path $runRoot "logs\${variant}_train.stdout.log") -RedirectStandardError (Join-Path $runRoot "logs\${variant}_train.stderr.log") -PassThru
    @{status='training'; current=$variant; pid=$process.Id; supervisor_pid=$PID; started_at=$started; completed=$finished; test_used=$false} | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath $statePath -Encoding utf8
    $process.WaitForExit()
    $process.Refresh()
    $exitCode = $process.ExitCode
    if ($null -eq $exitCode) { throw "Exit code unavailable for $variant" }
    $receipt = @{variant=$variant; started_at=$started; ended_at=(Get-Date).ToString('o'); exit_code=$exitCode; config=$configPath; output=$outputPath; args=$arguments; test_used=$false}
    $receipt | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath (Join-Path $runRoot "results\${variant}_exit.json") -Encoding utf8
    if ($exitCode -ne 0) { throw "$variant training failed, exit code $exitCode" }
    $finished += $variant
  }
  @{status='training_finished_awaiting_validation_audit'; completed=$finished; ended_at=(Get-Date).ToString('o'); C3='not_started_requires_C1_C2_validation_gates'; test_used=$false} | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath $statePath -Encoding utf8
} catch {
  @{status='failed'; current=$variant; error=$_.Exception.Message; completed=$finished; updated_at=(Get-Date).ToString('o')} | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath $statePath -Encoding utf8
  exit 1
}
